  "HelperA.dfy": "\n    if a != e {\n      var u := a;\n      O.Bounds(a, b, u);\n      A.Finish(a, b, e, u);\n    } else {\n      var u := b;\n      O.Bounds(a, b, u);\n      A.Finish(a, b, e, u);\n    }",
  "HelperB.dfy": "\n    if a != e {\n      var u := a;\n      O.Bounds(a, b, u);\n      A.Finish(a, b, e, u);\n    } else {\n      var u := b;\n      O.Bounds(a, b, u);\n      A.Finish(a, b, e, u);\n    }"
}
```

